import React, { useState } from 'react';
import toast from 'react-hot-toast';
import { login } from '../services/api';
import { Lock, Mail, ShieldCheck, Activity } from 'lucide-react';

export default function LoginPage({ onLogin }) {
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!password) return;
    setLoading(true);
    try {
      await login(password);
      toast.success('Access Granted. Syncing Dashboard...');
      onLogin();
    } catch {
      toast.error('Security protocol failed. Invalid passphrase.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-slate-50 relative overflow-hidden">
      {/* Decorative background elements */}
      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-primary-600 via-blue-400 to-indigo-600 shadow-[0_4px_12px_rgba(37,99,235,0.2)]" />
      <div className="absolute -top-24 -right-24 w-96 h-96 bg-primary-100/50 rounded-full blur-3xl" />
      <div className="absolute -bottom-24 -left-24 w-96 h-96 bg-blue-100/50 rounded-full blur-3xl" />

      <div className="w-full max-w-[440px] px-6 relative z-10 transition-all duration-700 animate-in fade-in zoom-in-95">
        <div className="bg-white p-10 rounded-3xl border border-slate-200 shadow-[0_20px_50px_rgba(0,0,0,0.05)]">
          {/* Brand */}
          <div className="flex flex-col items-center mb-10">
            <div className="w-16 h-16 bg-primary-600 rounded-2xl flex items-center justify-center text-white mb-6 shadow-xl shadow-primary-200 rotate-3">
              <Activity size={32} />
            </div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tight">Enterprise Console</h1>
            <p className="text-slate-500 font-medium text-sm mt-1">Payment Reconciliation & Dispatch</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-bold text-slate-500 uppercase tracking-widest">Master Key Access</label>
                <div className="flex items-center gap-1 text-[10px] font-bold text-green-600 bg-green-50 px-2 py-0.5 rounded-full border border-green-100">
                  <ShieldCheck size={10} /> ENCRYPTED
                </div>
              </div>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-600 transition-colors" size={20} />
                <input
                  type="password"
                  required
                  placeholder="Enter administrator passphrase"
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  autoFocus
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border-transparent focus:bg-white focus:border-primary-500 focus:ring-8 focus:ring-primary-100 rounded-2xl text-base transition-all outline-none placeholder:text-slate-400"
                />
              </div>
            </div>

            <button 
              type="submit" 
              disabled={loading} 
              className="w-full btn-primary h-14 rounded-2xl flex items-center justify-center gap-3 active:scale-[0.98] transition-all shadow-lg shadow-primary-100"
            >
              {loading ? (
                <div className="w-6 h-6 border-4 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                <>
                  <span className="text-base">Unlock Workstation</span>
                  <Activity size={18} />
                </>
              )}
            </button>
          </form>

          <div className="mt-10 pt-10 border-t border-slate-100">
            <div className="flex items-center justify-center gap-6">
               <div className="flex flex-col items-center gap-1 opacity-50 grayscale hover:grayscale-0 transition-all cursor-default">
                  <div className="text-[10px] font-bold text-slate-400">SMTP STACK</div>
                  <div className="h-0.5 w-6 bg-slate-300 rounded-full" />
               </div>
               <div className="flex flex-col items-center gap-1 opacity-50 grayscale hover:grayscale-0 transition-all cursor-default">
                  <div className="text-[10px] font-bold text-slate-400">DATA CLUSTER</div>
                  <div className="h-0.5 w-6 bg-slate-300 rounded-full" />
               </div>
            </div>
          </div>
        </div>

        <div className="mt-8 text-center flex flex-col gap-1">
          <p className="text-[11px] font-bold text-slate-400 uppercase tracking-widest">Proprietary Automation System</p>
          <p className="text-[10px] text-slate-400">© 2024 PayRecon Solutions v4.0.0-latest</p>
        </div>
      </div>
    </div>
  );
}
